// Sound instance volumes (no run-time property): patched in the project's .fev as FMOD reads it. The file
// (FNV-1a of the lower-case project name, i.e. its file name without .fev) and its size, the offset of the
// volume float, the PC and the console volume.
struct InstancePatch {
  uint32_t file_hash;
  uint32_t file_size;
  uint32_t offset;
  float pc;
  float console;
};

